pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 d, uint256 w1, uint256 extra, uint256 a) public {
        // keep the domain wide but admissible
        d = bound(d, 1, 1e30);
        w1 = bound(w1, 1, d);
        extra = bound(extra, 1, 1e30);
        // amount that exceeds the remaining recorded balance but not the raw Ether held
        a = bound(a, 1, 1e30);
        vm.assume(a > d - w1 && a <= d - w1 + extra);

        address actor = address(0xA11CE);
        vm.deal(actor, d);
        vm.prank(actor);
        c.deposit{value: d}();

        vm.prank(actor);
        c.withdraw(w1); // recorded balance is now d - w1

        // force extra Ether into c so the mutant's (un-checked) transfer can succeed
        vm.deal(address(this), extra);
        new ForceEther{value: extra}(address(c));

        vm.prank(actor);
        bool ok;
        try c.withdraw(a) { ok = true; } catch { ok = false; }

        // Rule: withdrawing more than the remaining recorded balance MUST revert,
        // regardless of the contract's raw Ether balance.
        assertTrue(!ok);
    }
}

contract ForceEther {
    constructor(address target) payable {
        selfdestruct(payable(target));
    }
}
}

