pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);

        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), amount);

        // deposit `amount` into c from the attacker
        attacker.deposit{value: amount}();

        bool ok;
        // withdraw: in the correct C, the balance is decremented before the
        // transfer's re-entrant callback, so the re-entry reverts and the whole
        // withdrawal reverts; the mutant lets the re-entry drain c again.
        try attacker.withdraw(amount) { ok = true; } catch { ok = false; }

        // Solvency rule: c's ether balance must always cover its recorded balances.
        assertTrue(address(c).balance >= c.balances(address(attacker)));
    }
}

contract ReentrantAttacker {
    C c;
    bool reentered;
    constructor(C _c) { c = _c; }
    function deposit() external payable { c.deposit{value: msg.value}(); }
    function withdraw(uint256 a) external { c.withdraw(a); }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdraw(msg.value);
        }
    }
}

