pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // admissible domain: at least 1 wei withdrawable, kept wide
        bound(amount, 1, 1 ether);

        Reentrant attacker = new Reentrant();
        attacker.setTarget(c);

        // attacker deposits amount + 1 so that amount is withdrawable and 1 wei remains
        vm.deal(address(attacker), amount + 1);
        vm.prank(address(attacker));
        c.deposit{value: amount + 1}();

        // attacker withdraws `amount`; during the transfer it re-enters and tries
        // to withdraw the remaining 1 wei.
        vm.prank(address(attacker));
        bool ok;
        try attacker.attack(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: with balance = amount + 1, withdrawing `amount` must SUCCEED
        // (the reference keeps balances[attacker] = amount+1 until after the payout,
        // so even the re-entrant 1-wei withdraw goes through). The mutant decrements
        // the balance to 1 BEFORE the transfer, so the re-entrant 1-wei withdraw hits
        // its require and the whole withdrawal reverts.
        assertTrue(ok);
    }
}

contract Reentrant {
    C c;
    bool locked;

    function setTarget(C c_) external { c = c_; }

    function attack(uint256 amount) external {
        c.withdraw(amount); // pays out to this contract -> receive() re-enters
    }

    receive() external payable {
        if (!locked) {
            locked = true;
            c.withdraw(1); // re-entrant withdraw of the remaining wei
        }
    }
}

