pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker atk;

    function setUp() public {
        c = new C();
        atk = new Attacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        vm.deal(address(atk), amount);
        bool ok;
        try atk.go(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: a funded withdrawer can always complete a withdrawal whose payout
        // merely re-enters to observe that its balance has not yet been decremented.
        assertTrue(ok, "withdrawal with re-entrant balance check must succeed");
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }

    function go(uint256 amount) external {
        c.deposit{value: amount}();
        c.withdraw(amount);
    }

    receive() external payable {
        // Re-enter only to READ state: during a correct payout our balance is not yet decremented.
        if (c.balances(address(this)) == 0) revert();
    }
}

