pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        vm.deal(address(attacker), amount);
        attacker.depositIn(amount);
        bool ok;
        try attacker.withdrawFrom(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: after depositing `amount`, a withdrawal of `amount` paid out to
        // a re-entrant party that deposits 1 wei during the payout always succeeds and
        // leaves exactly 1 wei credited to the caller.
        assertTrue(ok && c.balances(address(attacker)) == 1);
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }
    function depositIn(uint256 v) external payable {
        c.deposit{value: v}();
    }
    function withdrawFrom(uint256 amount) external {
        c.withdraw(amount);
    }
    receive() external payable {
        // re-enter during the payout: top the balance up by 1 wei
        c.deposit{value: 1}();
    }
}

