pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), amount);
        bool ok;
        try attacker.go(amount) { ok = true; } catch { ok = false; }
        // In the reference contract the caller's balance is still undiminished during the
        // payout, so a re-entrant refund tries to pay out ether the contract no longer
        // holds and reverts the entire withdrawal. The mutant zeroes the balance before
        // the transfer, so the re-entrant refund pays 0 and the withdrawal completes.
        assertTrue(!ok);
    }
}

contract Attacker {
    C c;
    bool hit;
    constructor(C _c) { c = _c; }
    function go(uint256 amount) external {
        c.deposit{value: amount}();
        hit = false;
        c.withdraw(amount);
    }
    receive() external payable {
        if (!hit) {
            hit = true;
            c.refund();
        }
    }
}

